for nm, kind, kcal, na in ITEMS:
    with contextlib.redirect_stdout(io.StringIO()):
        k, d = fa._search_gold(nm)
    check(d is not None and abs(d['cal'] - kcal) <= 1 and abs((d.get('sodium') or 0) - na) <= 2,
          f"{'교체' if kind == '교체' else '유지'} {nm} → {k} {d and (d['cal'], d.get('sodium'))} (기대 {kcal}·{na})")
print(f'test_value_check_v1: {n - len(fails)}/{n} 통과')
for m in fails: print('  ✗', m)
sys.exit(1 if fails else 0)
